import jax
import jax.numpy as jnp
import flax.linen as nn
from typing import Dict, Any, Sequence

# --- Hyperparameters ---
def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 512,
        'dropout_rate': 0.1,
        'cnn_kernel_sizes': [3, 5, 7], # For the advanced model
        'simple_cnn_kernel_size': 7 # For the simple model
    }

# --- Model 1: Simple 1D CNN (for CRI-Off) ---
class SimpleCNN(nn.Module):
    d_output: int
    task_type: str
    num_filters: int
    kernel_size: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        x = nn.Conv(features=self.num_filters, kernel_size=(self.kernel_size,))(x)
        x = nn.relu(x)
        x = jnp.mean(x, axis=1)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(features=self.d_output)(x)
        if self.task_type == "regression": return x.squeeze(-1)
        else: return x

# --- Model 2: CNN-BiLSTM-Attention (for all other tasks) ---
class Bidirectional(nn.Module):
    hidden_size: int
    @nn.compact
    def __call__(self, xs):
        forward_lstm = nn.RNN(nn.LSTMCell(features=self.hidden_size), name="forward")
        forward_output = forward_lstm(xs)
        reversed_xs = jnp.flip(xs, axis=1)
        backward_lstm = nn.RNN(nn.LSTMCell(features=self.hidden_size), name="backward")
        backward_output = jnp.flip(backward_lstm(reversed_xs), axis=1)
        return jnp.concatenate([forward_output, backward_output], axis=-1)

class Attention(nn.Module):
    @nn.compact
    def __call__(self, x):
        attention_weights = nn.Dense(features=x.shape[-1])(x)
        attention_weights = nn.tanh(attention_weights)
        attention_weights = nn.Dense(features=1)(attention_weights)
        attention_weights = nn.softmax(attention_weights, axis=1)
        return jnp.sum(x * attention_weights, axis=1)

class AdvancedModel(nn.Module):
    d_output: int
    task_type: str
    num_filters: int
    cnn_kernel_sizes: Sequence[int]
    lstm_hidden_size: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        cnn_outputs = []
        for kernel_size in self.cnn_kernel_sizes:
            conv_out = nn.Conv(features=self.num_filters, kernel_size=(kernel_size,))(x)
            cnn_outputs.append(conv_out)
        x = jnp.concatenate(cnn_outputs, axis=-1)
        x = nn.relu(x)
        x = Bidirectional(hidden_size=self.lstm_hidden_size)(x)
        x = Attention()(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(features=self.d_output)(x)
        if self.task_type == "regression": return x.squeeze(-1)
        else: return x

# --- Universal Wrapper and Conditional Logic ---
class NetworkWrapper:
    def __init__(self, network_module):
        self.network = network_module

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = jax.random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None: rng_key = jax.random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    dataset_name = hparams.get("dataset")

    if dataset_name == "CRI-Off":
        # Use the simple, robust CNN for this specific noisy task
        simple_cnn_module = SimpleCNN(
            d_output=hparams.get("d_output", 1),
            task_type=hparams.get("task_type", "regression"),
            num_filters=hparams.get("hidden_dim", 512),
            kernel_size=hparams.get("simple_cnn_kernel_size", 7),
            dropout_rate=hparams.get("dropout_rate", 0.1)
        )
        return NetworkWrapper(simple_cnn_module)
    else:
        # Use the high-performing advanced model for all other tasks
        num_kernels = len(hparams.get("cnn_kernel_sizes", [3, 5, 7]))
        advanced_model_module = AdvancedModel(
            d_output=hparams.get("d_output", 1),
            task_type=hparams.get("task_type", "regression"),
            num_filters=hparams.get("hidden_dim", 512) // num_kernels,
            cnn_kernel_sizes=hparams.get("cnn_kernel_sizes", [3, 5, 7]),
            lstm_hidden_size=hparams.get("hidden_dim", 512) // 2,
            dropout_rate=hparams.get("dropout_rate", 0.1)
        )
        return NetworkWrapper(advanced_model_module)
